insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values (E'6fac97bd-20dd-50fd-bed0-f1f084d0ec56',E'Criterios y estándares técnicos y conceptuales para la conservación y resguardo de la Información de Interés Nacional',E'CECR-IIN',null,null,true,ARRAY[E'SNIEG',E'INEGI',E'Información de Interés Nacional',E'Acervo IIN',E'Conservación',E'Resguardo']::text[],E'https://www.snieg.mx/Documentos/Normatividad/Vigente/criteros_estandares_tecnicos_conceptuales_cons_y_resgiin.pdf',E'manual') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'403b9494-e977-5a6b-9ceb-1541e5a13aeb',E'Presentación · pág. 2',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Presentación\nLos Criterios y estándares técnicos y conceptuales para la\nconservación y resguardo de la Información de Interés Nacional,\nforma parte del conjunto de documentos derivados de las Reglas de\nintegración y administración del Acervo de Información de Interés\nNacional, publicadas en el Diario Oficial de la Federación el 4 de\ndiciembre de 2014.\nLa adopción de criterios y estándares facilita, en este caso, la\nvinculación y coordinación de los integrantes del SNIEG mediante una\nRed de Resguardo que apoya la integración, conservación y\nresguardo del Acervo de Información de Interés Nacional.\nLa Red de Resguardo incluye un Nodo Central y Nodos en cada una\nde las Unidades del Estado que producen Información de Interés\nNacional, así como el Acervo de IIN. Mientras el Acervo de IIN se\ncompone de información digital contenida en repositorios, los Nodos\nson sistemas informáticos que facilitan la administración y acceso a\nestos para conservar y resguardar la Información de Interés Nacional\nen cada UE.\nEl INEGI emite este documento en donde se establecen las bases\nconceptuales y técnicas para normar las actividades de conservación\ny resguardo de la IIN, incluidas las especificaciones para los Nodos, los\ntipos de datos y sus formatos y la incorporación de información.\nEl presente documento está sujeto a revisión por parte del INEGI y\ncualquier actualización será publicada en el Portal del SNIEG.\nAsimismo,   es  complementario    de   los  siguientes  documentos\nnormativos:\n  Esquema de entrega-recepción de la Información de Interés\n   Nacional.\n  Medidas de conservación y resguardo de la Información de Interés\n   Nacional.</pre></div></section>',E'anexo',1,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Criterios y estándares de conservación y resguardo',E'Presentación',E'6fac97bd-20dd-50fd-bed0-f1f084d0ec56') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'ebfaa62e-347c-525c-9d31-7534d71cd73b',E'Marco legal y criterios generales · pág. 4',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">1. Marco legal\n   La Ley del Sistema Nacional de Información Estadística y Geográfica (LSNIEG) establece\n   que el Sistema Nacional de Información Estadística y Geográfica, es el conjunto de\n   Unidades organizadas a través de los Subsistemas, coordinadas por el Instituto y articuladas\n   mediante la Red Nacional de Información, con el propósito de producir y difundir la\n   Información de Interés Nacional.\n   La LSNIEG define la Red Nacional de Información como el conjunto de procesos de\n   intercambio y resguardo de Información, para apoyar por un lado las actividades de\n   coordinación del Sistema y de sus Subsistemas y por otro la prestación del Servicio Público\n   de Información a toda la sociedad.\n   En el mismo ordenamiento, se establece que las Unidades del Estado distintas al Instituto,\n   cuando    desarrollen  actividades   relacionadas   con   la  producción,   integración,\n   conservación y difusión de Información de Interés Nacional, deberán: resguardar y\n   conservar la Información, así como los metadatos o especificaciones concretas de la\n   aplicación de las metodologías que hubieren utilizado en la elaboración de la misma, en\n   la forma y términos que, previo acuerdo con el coordinador de la Unidad que corresponda,\n   señale el Instituto.\n   Se establece también que el Instituto deberá conservar la Información de Interés Nacional\n   que elaboren el propio Instituto y las Unidades, en términos de lo dispuesto en la propia Ley\n   del SNIEG y en las disposiciones de carácter general que al efecto emita el Instituto.\n   Cuando una Unidad desaparezca o se desincorpore, el Instituto deberá conservar la\n   Información generada por la misma.\n   Asimismo, las Reglas para la integración y administración del Acervo de IIN, establecen\n   disposiciones para el Acervo en donde se señala que mediante el presente documento se\n   desarrollan los siguientes criterios y estándares para su conservación y resguardo:\n2. Criterios generales\n    2.1 El Coordinador del Acervo se apoyará en el Director General Adjunto de Planeación\n         e Infraestructura del INEGI quien fungirá como Administrador del Acervo de IIN.\n    2.2 Las Unidades del Estado son responsables de entregar al INEGI una copia de la\n         Información de Interés Nacional que hayan publicado, junto con los metadatos y\n         metodologías utilizadas, bajo los criterios y estándares que se emiten en este\n         documento para llevar a cabo la integración del Acervo de Información de Interés\n         Nacional (Acervo de IIN o AIIN).\n    2.3 Cada Unidad del Estado es responsable de la conservación y resguardo en su propio\n         repositorio, de la Información de Interés Nacional que produce, así como de los\n         metadatos y de las metodologías que hayan sido utilizadas. A su vez el INEGI es\n         responsable de conservar las copias de todo aquello que se encuentre en el Acervo\n         de IIN.\n    2.4 El Acervo de IIN estará conformado por la Información que el INEGI integre al Nodo\n         Central, contenida en forma electrónica. En caso de que sea necesario, la UE deberá\n         conservar y resguardar la información que se encuentre en medios impresos sin que\n         ésta se considere parte del Acervo.</pre></div></section>',E'anexo',2,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Criterios y estándares de conservación y resguardo',E'Marco legal y criterios generales',E'6fac97bd-20dd-50fd-bed0-f1f084d0ec56') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'1e6883cb-1b76-5b77-a58c-763aa8d27181',E'Criterios generales y específicos · pág. 5',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">    2.5 El INEGI integrará al Acervo de IIN para su conservación, la IIN, metadatos,\n         metodologías, y especificaciones concretas de la aplicación de éstas en la\n         producción de la IIN. Para realizar dicha tarea, el Instituto desarrollará y administrará\n         un repositorio central que compartirá con las Unidades del Estado responsables de\n         generar la Información, a través de la Red Nacional de Información.\n    2.6 En caso de que la Información se genere de manera colegiada por un grupo de\n         trabajo integrado por dos o más UE, el grupo acordará la designación del\n         Responsable de la IIN y del Responsable Informático ante el Coordinador del Acervo,\n         los cuales también se encargarán de la creación, actualización y mantenimiento del\n         repositorio y del Nodo en la UE a la que pertenezca el Responsable de la IIN y de la\n         entrega de la copia correspondiente al INEGI para su integración al Acervo de IIN.\n    2.7 El Instituto y las Unidades del Estado que producen IIN serán responsables de\n         incorporar en su plataforma informática los mecanismos y componentes de\n         hardware y software necesarios para dar soporte y proteger tanto a su repositorio\n         como a su Nodo, contra amenazas informáticas como el acceso, modificación,\n         destrucción o copiado, no autorizados a la información de las Unidades del Estado,\n         así como la documentación correspondiente.\n    2.8 El Acervo de IIN, así como el conjunto de Nodos y repositorios de las Unidades del\n         Estado y del INEGI, son parte de la Red de Resguardo de Información de Interés\n         Nacional.\n3. Criterios específicos\n    3.1 Sobre la Información de Interés Nacional a integrarse en el Acervo:\n         3.1.1 La información que se entregue por parte de las UE para integrarse en el Acervo\n              de IIN debe cumplir con lo siguiente:\n                a. Que se trate de Información de Interés Nacional.\n                b. Haber sido publicada en el Servicio Público de Información.\n                c. Debe tratarse de Información con carácter definitivo.\n         3.1.2 Cada entrega de IIN que haga la UE al INEGI deberá ser una instancia del\n              conjunto de datos de IIN correspondientes a un determinado proyecto,\n              conforme a lo publicado por la Junta de Gobierno del INEGI en cumplimiento\n              del Artículo Décimo Tercero Transitorio de la Ley del SNIEG o de un Acuerdo\n              publicado en el Diario Oficial de la Federación conforme al Artículo 77 de la\n              Ley del SNIEG. Existen dos tipos de instancia de IIN: completa y de actualización.\n         3.1.3 Una instancia completa de IIN se considera como la IIN correspondiente a una\n              fecha específica de publicación oficial de Información definitiva, incluyendo\n              sus metadatos, metodologías y las especificaciones concretas de su\n              aplicación.\n         3.1.4 Una instancia de actualización de IIN se considera como la IIN definitiva\n              derivada de una instancia completa de IIN, publicada oficialmente en una\n              fecha posterior y para la que no hubo modificaciones en sus metadatos, ni en\n              sus metodologías.\n         3.1.5 La Unidad del Estado definirá los contenidos que conforman:\n                a. Una instancia completa de IIN.\n                b. Una instancia de actualización de IIN</pre></div></section>',E'anexo',3,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Criterios y estándares de conservación y resguardo',E'Criterios generales y específicos',E'6fac97bd-20dd-50fd-bed0-f1f084d0ec56') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'95e3da38-890e-550d-863c-6f371179a71a',E'Instancias completas y de actualización · pág. 6',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">3.1.6 A fin de que se disponga fácilmente de la IIN y pueda interpretarse\n      correctamente, cada instancia completa de IIN deberá contener por lo\n      menos:\n       a. Los contenidos de la IIN definitiva generada a la fecha de publicación\n          oficial.\n       b. Los metadatos estructurales, como denominación, referencia geográfica,\n          referencia temporal, unidad de análisis, unidades de medida y aquellas\n          otras dimensiones y atributos, que se consideren necesarios para\n          interpretar los datos.\n       c. Los metadatos de referencia, que incluyan entre otros, descripciones sobre\n          su procedencia, proceso de producción, responsable de su actualización\n          y características generales de la Información, y de su documentación.\n       d. Los metadatos administrativos, que incluyan datos técnicos sobre la\n          creación, almacenamiento, control de acceso y calidad, gestión de\n          recursos y derechos, condiciones de preservación, mantenimiento,\n          entrega y migración, entre otros.\n       e. Las metodologías utilizadas y las especificaciones concretas de su\n          aplicación en la elaboración de la IIN.\n       f. Bitácora, en el caso de que se realice algún ajuste a la IIN definitiva que\n          deba justificar el movimiento aplicado.\n       g. Aquella información adicional que el Responsable de IIN considere sea\n          necesaria para complementar la información en lo referente a su\n          contenido, contexto y/o estructura.\n3.1.7 Cada instancia de actualización de IIN contendrá al menos lo establecido en\n      los incisos a) y b) del numeral anterior, así como la información aplicable del\n      inciso f).\n3.1.8 Cuando haya cambios en la composición o definición conceptual de los\n      metadatos, en las metodologías o en las especificaciones concretas de su\n      aplicación en la elaboración de la IIN, se deberá entregar una instancia\n      completa de IIN.\n3.1.9 El contenido del conjunto de elementos definidos para las instancias completa\n      y de actualización, deberán permitir que la IIN que se integre al Acervo:\n       a. Conserve la autenticidad, integridad y disponibilidad de la información en\n          el tiempo.\n       b. Conserve las características descritas en el Artículo 78 de la Ley del SNIEG.\n       c. Mantenga las características de calidad, pertinencia y veracidad.\n       d. Cumpla con las disposiciones normativas vigentes en materia de derechos\n          de autor.\n       e. Preserve los principios de confidencialidad y reserva, alineados a Ley\n          Federal  de   Transparencia   y   Acceso   a   la  Información   Pública\n          Gubernamental.\n       f. Se almacene completamente en medios digitales.\n       g. Pueda recuperarse íntegramente de los medios de almacenamiento que\n          la contengan.\n       h. Pueda ser leída y procesada por medios computacionales.</pre></div></section>',E'anexo',4,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Criterios y estándares de conservación y resguardo',E'Instancias completas y de actualización',E'6fac97bd-20dd-50fd-bed0-f1f084d0ec56') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'e44a69c3-f125-585d-9eda-bede9c4c68d7',E'Archivos digitales y Nodo Central · pág. 7',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">   3.1.10 Cada elemento deberá ser entregado en formato digital y cumplir con las\n           características establecidas en la sección “Sobre las características de los\n           archivos digitales” de este documento.\n   3.1.11 Toda instancia que se entregue deberá estar acompañada de un archivo que\n           contenga la relación de los archivos que conforman dicha instancia, con base\n           en lo señalado en el documento Esquema de entrega recepción de la\n           Información de Interés Nacional.\n3.2 Sobre las características de los archivos digitales\n     3.2.1 Los archivos deberán ser compatibles con la estructura de sistema de archivos\n           bajo el estándar NTFS (New Technology File System - Sistema de Archivos de\n           Nueva Tecnología).\n     3.2.2 El nombre de cada archivo y/o carpeta deberá referenciar a su contenido,\n          conformado con letras sin acentos, caracteres especiales, ñ, utilizando el guion\n          bajo para separar palabras. Con extensión máxima de 250 caracteres\n          incluyendo la ruta.\n     3.2.3 Conforme al tipo de contenido, los archivos deberán ser entregados en alguno\n           de los formatos que se indican en Anexo 1: Tipos de archivos. Aquellos\n           contenidos que no se ajusten a ninguno de los formatos indicados en el Anexo\n           1, deberán ser entregados en archivos bajo formatos abiertos, incluyendo la\n           especificación   tecnológica   completa    del  formato   que   permita   su\n           interpretación, visualización y uso.\n     3.2.4 Se deberán comprimir en un formato de uso común (zip) los archivos mayores\n           a 100 MB.\n     3.2.5 Todo archivo que se entregue deberá ser acompañado por una ficha de\n           metadatos de preservación conforme se especifica en el Anexo 2: Formato de\n           Metadatos de Preservación de Archivos.\n3.3 Sobre el Nodo Central del Acervo\n     3.3.1 El Instituto desarrollará el Nodo Central consistente en un sistema informático\n           que facilite la administración y el acceso al Acervo de Información de Interés\n           Nacional.\n     3.3.2 Las actividades concernientes a la administración del Nodo Central deberán\n           comprender:\n           a. La recepción, validación, integración y actualización de la IIN con su\n             documentación correspondiente.\n           b. La integración y actualización del inventario de Información Estadística y\n             Geográfica de Interés Nacional.\n           c. La integración y actualización del inventario de archivos contenidos en el\n             Nodo Central.\n           d. La implementación de las medidas de Seguridad de la Información\n             conforme al documento Medidas de conservación y resguardo de la IIN,\n             emitido por el Instituto.\n           e. El registro de los Responsables de IIN e Informáticos de las UE, conforme al\n             Anexo 3: Formato de registro de responsables para el Acervo de IIN.</pre></div></section>',E'anexo',5,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Criterios y estándares de conservación y resguardo',E'Archivos digitales y Nodo Central',E'6fac97bd-20dd-50fd-bed0-f1f084d0ec56') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'06bf7f4a-78e7-55a9-bfbb-f1bdbfb63043',E'Nodos de las Unidades del Estado · pág. 8',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">           f. El registro de los Nodos de las UE, conforme al Anexo 4: Formato de registro\n             de Nodo de la Unidad del Estado.\n           g. Soporte a consultas y solicitudes de información.\n3.4 La integración de la IIN y su documentación en el Nodo Central\n     3.4.1 La IIN y documentación correspondiente que se integren en el Nodo Central\n           deberá ser aquélla publicada con carácter de definitiva.\n     3.4.2 La periodicidad de actualización se realizará conforme a lo registrado por la UE\n           en el formato de identificación de la instancia de IIN, a partir de lo que se\n           conformará el calendario del Acervo.\n     3.4.3 Las UE deberán proporcionar al Instituto copia de la IIN que hayan incorporado\n           en su repositorio, dentro de los 10 días hábiles posteriores a su depósito o\n           actualización.\n     3.4.4 El Instituto integrará las copias de la IIN que reciba de las UE al Acervo.\n3.5 Sobre los Nodos de las Unidades del Estado\n     3.5.1 Corresponde a las Unidades del Estado el desarrollo de su Nodo para facilitar la\n           administración y el acceso a la IIN que producen.\n     3.5.2 Las UE deberán incorporar en su repositorio la IIN definitiva, que hayan\n           publicado en un plazo máximo de 30 días.\n     3.5.3 Las actividades concernientes a la administración del Nodo de la UE deberán\n           comprender:\n           a. Resguardar, validar, registrar, integrar y actualizar la IIN con su\n             documentación correspondiente.\n           b. La integración y actualización del inventario del conjunto de archivos\n             contenidos en su Nodo.\n           c. La implementación de las medidas de Seguridad de la Información\n             conforme al documento Medidas de conservación y resguardo de la IIN,\n             emitido por el Instituto.\n           d. La generación de respaldos útiles conforme a lo establecido en el\n             documento Medidas de conservación y resguardo de Información de\n             Interés Nacional.\n           e. Soporte a consultas y solicitudes de información.\n   3.6 La integración de la IIN y su documentación en los Nodos de las UE\n     3.6.1 La IIN y documentación correspondiente que integre y actualice en su Nodo\n           cada UE deberá ser aquélla publicada con carácter de definitiva.\n     3.6.2 La integración de IIN y documentación correspondiente deberá ser conforme\n           al Artículo 15 de las Reglas para la integración y administración del Acervo de\n           IIN.\n     3.6.3 La UE deberá integrar a su Nodo la IIN que produce dentro de los diez días\n           hábiles siguientes a su publicación con carácter definitivo.\n Para la aplicación de los criterios, el Instituto proporcionará la asesoría que le sea\n requerida.</pre></div></section>',E'anexo',6,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Criterios y estándares de conservación y resguardo',E'Nodos de las Unidades del Estado',E'6fac97bd-20dd-50fd-bed0-f1f084d0ec56') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'fbf75f63-9f57-5c2c-864e-d8655aea6623',E'Glosario · primera parte · pág. 9',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans"> Glosario\n                 Conjunto de Información de Interés Nacional que ya ha sido difundida por el\n       Acervo de\n                 Servicio Público de Información, así como sus metadatos, metodologías y/o\n    Información o\n                 especificaciones concretas de la aplicación de las metodologías utilizadas en su\n         Acervo\n                 generación.\n                 Establecimiento de un conglomerado demográfico, con el conjunto de sus sistemas\n    Asentamiento\n                 de convivencia, en un área físicamente localizada, considerando dentro de la\n        humano\n                 misma los elementos naturales y las obras materiales que lo integran.\n                 Conjunto de procedimientos y medidas para asegurar la preservación de datos del\n Conservación de\n                 Acervo y prevenir la ocurrencia de alteraciones físicas en sus medios de\n   la Información\n                 almacenamiento.\n Coordinador del\n        Acervo o  El Director General de Coordinación del SNIEG.\n     Coordinador\n                 Es aquella que se encuentre identificada, estructurada y almacenada en los\n                 medios y formatos que establezca el Instituto para el respaldo de la Información\n                 de Interés Nacional de las Unidades del Estado que formará parte del Acervo, a\n      Copia útil\n                 la cual se puede acceder directamente para su consulta y/o procesamiento\n                 utilizando los medios computacionales existentes, sin que haya afectaciones a la\n                 integridad de sus contenidos.\n                 Conjunto de documentos que acompañan a la Información de Interés Nacional en\n Documentación   su conservación y resguardo: metadatos, metodologías y/o especificaciones\n                 concretas de la aplicación de las metodologías utilizadas en su elaboración.\n    Estándar NTFS Especifica qué usuarios, grupos y equipos pueden acceder a los archivos y carpetas\n                 y también qué pueden hacer con su contenido.\n  INEGI o Instituto Al Instituto Nacional de Estadística y Geografía.\n                 A la señalada en el artículo 59 de la Ley del Sistema Nacional de Información\n  Información de\n                 Estadística y Geográfica (LSNIEG), así como aquella que la Junta de Gobierno\n Interés Nacional,\n                 determine como tal, de acuerdo con lo establecido en los artículos 77 fracción II y\n Información o IIN\n                 78 de dicha Ley.\n      Metadatos  Descripción estandarizada de las características de un grupo de datos estadísticos\n                 o geográficos.\n    Metodología Procedimiento que ordena y articula el conjunto particular de actividades\n                 necesarias para producir información estadística y/o geográfica.\n    Nodo Central Sistema informático para facilitar la administración y acceso del repositorio digital\n                 creado por el INEGI en donde se conserva y resguarda el Acervo de IIN.\nNodo    de    la  Sistema informático para facilitar la administración y acceso del repositorio digital\nUnidad del Estado  creado por cada Unidad del Estado en donde se conserva, resguarda y actualiza\no Nodo           su Información de Interés Nacional y su documentación.\n                 Conjunto de Información, metodologías y metadatos, o alguno de estos elementos,\n                 que se incorpora al Repositorio/Nodo Central del Acervo en cada entrega que\n  Instancia de IIN\n                 hace la Unidad del Estado productora.</pre></div></section>',E'anexo',7,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Criterios y estándares de conservación y resguardo',E'Glosario · primera parte',E'6fac97bd-20dd-50fd-bed0-f1f084d0ec56') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'9536edd2-650e-5e3c-8eb4-56af0a8f1a22',E'Glosario · segunda parte · pág. 10',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">         Red de\n   Resguardo de\n                 Red distribuida a través de la cual cada Unidad de Estado y el propio Instituto, se\n  Información de\n                 apoyarán para vincularse y coordinarse a fin de integrar, conservar y resguardar el\nInterés Nacional o\n                 Acervo de IIN.\n         Red de\n      Resguardo\n                 Conjunto de procesos de intercambio y resguardo de Información, para apoyar por\n Red Nacional de\n                 un lado las actividades de coordinación del Sistema y de sus Subsistemas y por otro\nInformación o RNI\n                 la prestación del Servicio Público de Información a toda la sociedad.\n      Repositorio Sistema electrónico de almacenamiento de información.\n                 Protección de la Información y su documentación, que se implementa en los\n   Resguardo de\n                 Nodos, contra accesos no autorizados, alteraciones, daños físicos, pérdida total o\n   la Información\n                 parcial, entre otros.\n    Responsable  Servidor público designado por cada Unidad del Estado generadora de IIN,\n        de la IIN  responsable de la conservación y resguardo de la misma.\n     Responsable\n    Informático o  Servidor público designado por cada Unidad del Estado generadora de IIN,\n     Responsable  responsable de otorgar las condiciones informáticas adecuadas para la\n   Informático de  conservación y resguardo de la Información.\n            la UE\n    Responsable  Servidor público designado por el titular de la Dirección General Adjunta de\n      Informático  Informática, que tenga a su cargo la responsabilidad sobre la coordinación y/o\n     del Instituto  administración del servicio informático del Nodo Central.\n  Seguridad de la  Capacidad de preservar la confidencialidad, Integridad y disponibilidad de la\n     Información  Información a partir de la implementación de medidas técnicas y organizativas</pre></div></section>',E'anexo',8,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Criterios y estándares de conservación y resguardo',E'Glosario · segunda parte',E'6fac97bd-20dd-50fd-bed0-f1f084d0ec56') on conflict(id) do nothing;
