insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'2ba15a37-c623-5afb-bc21-807147396539',E'Anexo 4 · Instructivo de llenado · pág. 15',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Instructivo de llenado\n                    Identificación de la UE productora y características de la IIN\n  1. Unidad del Estado\n                                  Indique conforme lo señala el artículo 2 fracción XV de la Ley del\n                                  SNIEG.\n                                  Si la UE cuenta con siglas que la identifiquen se anotan aquí.\n  Siglas\n                                  Proporcione los datos que se solicitan sobre la ubicación física\n  2. Dirección\n                                  del Nodo de la UE productora.\n                                  Nombre y apellidos del Responsable Informático de la UE\n  3. Responsable Informático      productora de la IIN que llena el formato y su puesto; el teléfono\n                                  y correo electrónico son los institucionales.\n                                  Utilizar el orden de año con cuatro dígitos, mes y día con dos\n  4. Fecha de llenado del registro\n                                  dígitos.\n                                  Indicar con X el subsistema al que pertenece la IIN:\n                                  1. Demográfica y social.\n   5. Subsistema Nacional de      2. Económica.\n    Información\n                                  3. Geográfica, Medio Ambiente, Ordenamiento Territorial y\n                                  Urbano.\n                                  4. De Gobierno, Seguridad Pública e Impartición de Justicia.\n                                  Indique el método de acceso a la información, url ftp,\n  6. Acceso al Nodo de la UE\n                                  especifique algún otro.\n                                  Describa los detalles tecnológicos del sistema en donde se\n  7. Especificaciones tecnológicas\n                                  administra el Nodo, si se requiere autenticación, o algún\n    del sistema de administración\n                                  requerimiento específico para el acceso a este, así como\n    del Acervo\n                                  cualquier otro detalle.\n                                  Indique las especificaciones del hardware del Nodo, servidores,\n  8. Especificaciones de hardware  espacio de almacenamiento, procesamiento, memoria, sistema\n                                  operativo, etc.\n  9. Especificaciones de software  Indique el software utilizado y la versión de este.\n 10. Especificaciones de bases de  Indique el tipo de almacenamiento de datos utilizado, tipos de\n    datos                         servidores y/o motores de bases de datos.</pre></div></section>',E'anexo',13,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Criterios y estándares de conservación y resguardo',E'Anexo 4 · Instructivo de llenado',E'6fac97bd-20dd-50fd-bed0-f1f084d0ec56') on conflict(id) do nothing;
